async function drsFixture(){const env=fixture(),matchId=await create(env,'matches',{name:'Synthetic isolated DRS match',teamA:'A',teamB:'B',overs:10});const data=await get(env,matchId);data.events=[{eventType:'delivery',innings:1,runs:0}];await env.DB.prepare('UPDATE records SET data=? WHERE id=?').bind(JSON.stringify(data),matchId).run();const cameras=[];for(let i=0;i<2;i++){const registered=await call(env,'hardware/devices','POST',{name:'Synthetic camera '+i,serial:'DRS-TEST-'+i,model:'Test',recordingConsent:true});assert.equal(registered.status,201);const credential=await call(env,'hardware/devices/'+registered.data.id+'/credential','POST',{version:1});cameras.push({id:registered.data.id,token:credential.data.token})}return {env,matchId,cameras,setup:{version:0,bowler_end:cameras[0].id,square_leg:cameras[1].id,placementNote:'Synthetic isolated placement declaration'}}}
test('DRS requires distinct owner cameras, authorised officials, actual acknowledgements and fresh alignment for managed broadcasts',async()=>{
 const {env,matchId,cameras,setup}=await drsFixture();assert.equal((await call(env,'drs/'+matchId+'/setup','POST',setup,'bob')).status,403);assert.equal((await call(env,'drs/'+matchId+'/setup','POST',{...setup,square_leg:setup.bowler_end})).status,400);assert.equal((await call(env,'drs/'+matchId+'/setup','POST',setup)).status,200);
 const post={name:'Synthetic broadcast',postType:'Live',cricketOnly:true,sourceMatchId:matchId,broadcastSource:'18-camera',url:'https://youtu.be/abcdefghijk'};assert.equal((await call(env,'records','POST',{type:'community',data:post})).status,400);assert.equal((await call(env,'drs/'+matchId+'/setup','POST',{...setup,version:1,syncConfirmed:true})).status,400);
 for(const camera of cameras){await cameraIngest(env,camera.token,{action:'heartbeat'});const session=await call(env,'hardware/sessions','POST',{deviceId:camera.id,matchId});assert.equal(session.status,201);assert.equal((await cameraIngest(env,camera.token,{action:'recording_started',sessionId:session.data.id})).status,200)}
 assert.equal((await call(env,'drs/'+matchId+'/setup','POST',{...setup,version:1,syncConfirmed:true})).status,200);assert.equal((await call(env,'drs/'+matchId)).data.readiness.ready,true);const published=await call(env,'records','POST',{type:'community',data:post});assert.equal(published.status,201,JSON.stringify(published.data));assert.equal((await call(env,'data')).data.records.find(r=>r.id===published.data.id).drsReady,true);
 await env.DB.prepare('UPDATE hardware_devices SET token_hash=NULL WHERE id=?').bind(cameras[0].id).run();const paused=(await call(env,'data')).data.records.find(r=>r.id===published.data.id);assert.equal(paused.drsReady,false);assert.equal(paused.embedUrl,undefined);assert.equal((await call(env,'drs/'+matchId)).data.readiness.ready,false);
 assert.equal((await call(env,'records','POST',{type:'community',data:{...post,broadcastSource:'external'}})).status,201);
});
test('DRS final decisions are immutable, unknown evidence retains original, stale scorecards conflict and score data never changes',async()=>{
 const {env,matchId,setup}=await drsFixture();await call(env,'drs/'+matchId+'/setup','POST',setup);const open={matchVersion:1,eventIndex:0,type:'lbw',originalDecision:'not_out',referral:'umpire'};
 assert.equal((await call(env,'drs/'+matchId+'/reviews','POST',open,'bob')).status,403);assert.equal((await call(env,'drs/'+matchId+'/reviews','POST',{...open,referral:'player'})).status,400);assert.equal((await call(env,'drs/'+matchId+'/reviews','POST',{...open,eventIndex:9})).status,400);
 const created=await call(env,'drs/'+matchId+'/reviews','POST',open);assert.equal(created.status,201);const endpoint='drs/'+matchId+'/reviews/'+created.data.id,payload={version:1,observations:{clearEvidence:'yes',noBall:'no',freeHit:'no',batFirst:'no',pitch:'inline',impact:'inline',shot:'yes',trajectory:'hitting'},aligned:true,decision:'out',reason:'Synthetic isolated evidence test',evidence:['bowler_end','square_leg'].map(role=>({role,url:'https://youtu.be/abcdefghijk',seconds:1}))};
 assert.equal((await call(env,endpoint,'POST',payload)).status,400);assert.equal((await call(env,endpoint,'POST',{...payload,decision:'retain_original',evidence:[payload.evidence[0]]})).status,400);const final=await call(env,endpoint,'POST',{...payload,decision:'retain_original'});assert.equal(final.status,200);assert.equal(final.data.scorecardChanged,false);assert.equal(final.data.evaluation.automatedDetection,false);assert.equal((await call(env,endpoint,'POST',{...payload,decision:'retain_original',version:2})).status,409);
 const stale=await call(env,'drs/'+matchId+'/reviews','POST',open);await env.DB.prepare('UPDATE records SET version=version+1 WHERE id=?').bind(matchId).run();assert.equal((await call(env,'drs/'+matchId+'/reviews/'+stale.data.id,'POST',{...payload,decision:'retain_original'})).status,409);assert.equal((await call(env,'drs/'+matchId)).data.reviews.every(r=>r.stale),true);assert.equal((await get(env,matchId)).events.length,1);
});
