function fixture(){const sqlite=new DatabaseSync(':memory:');for(const file of readdirSync(new URL('../drizzle/',import.meta.url)).filter(f=>f.endsWith('.sql')).sort())sqlite.exec(readFileSync(new URL('../drizzle/'+file,import.meta.url),'utf8'));const DB={prepare(sql){const statement=sqlite.prepare(sql);return {args:[],bind(...args){this.args=args;return this},async all(){return {results:statement.all(...this.args)}},async first(){return statement.get(...this.args)||null},async run(){const r=statement.run(...this.args);return {meta:{changes:Number(r.changes)}}}}},async batch(queries){sqlite.exec('BEGIN');try{const result=[];for(const q of queries)result.push(await q.run());sqlite.exec('COMMIT');return result}catch(e){sqlite.exec('ROLLBACK');throw e}}};return {DB}}
async function call(env,path,method='GET',body,user='alice',origin){if(user&&!env.skipAutoProfile&&!['account','status'].includes(path.split('/')[0])){const row=await env.DB.prepare('SELECT data FROM accounts WHERE owner=?').bind(user).first(),old=row?JSON.parse(row.data):{};const p={name:'Synthetic member',city:'Test city',country:'US',roles:['player'],primaryRole:'player',...old,consent:{termsAccepted:true,privacyAccepted:true,policyVersion:'2026-10-08',acceptedAt:'2026-10-08T00:00:00Z'}};if(!row)await env.DB.prepare('INSERT OR IGNORE INTO accounts(owner,email,data,created,updated) VALUES(?,?,?,?,?)').bind(user,user+'@example.test',JSON.stringify(p),'test','test').run();else await env.DB.prepare('UPDATE accounts SET data=? WHERE owner=?').bind(JSON.stringify(p),user).run();}const headers={'Content-Type':'application/json'};if(user){headers['oai-authenticated-user-id']=user;headers['oai-authenticated-user-email']=user+'@example.test';}if(origin)headers.origin=origin;const r=await handle(new Request('https://cricket.test/api/'+path,{method,headers,body:body===undefined?undefined:JSON.stringify(body)}),env);return {status:r.status,data:await r.json()}}
async function create(env,type,data,user='alice'){const r=await call(env,'records','POST',{type,data},user);assert.equal(r.status,201,JSON.stringify(r.data));return r.data.id}
async function get(env,id){return (await call(env,'data')).data.records.find(r=>r.id===id)}
