import {calculateMatch,appendCommand} from '../public/scoring-engine.js';
const pro=()=>({name:'Test derby',teamA:'A',teamB:'B',overs:2,proScoring:true,squads:{A:[1,2,3].map(id=>({id:'a'+id,name:'A'+id})),B:[1,2,3].map(id=>({id:'b'+id,name:'B'+id}))},scoringConfig:{maxBowlerOvers:1,freeHit:true},events:[]});
const selected=()=>appendCommand(pro(),{command:'select',strikerId:'a1',nonStrikerId:'a2',bowlerId:'b1'});
test('attributed ledger reconciles bat runs, byes, no-balls and wide free-hit carryover',()=>{let m=selected();m=appendCommand(m,{runs:4,boundary:4});m=appendCommand(m,{runType:'bye',runs:2});m=appendCommand(m,{noBall:true,runs:2});let v=calculateMatch(m);assert.equal(v.first.runs,9);assert.equal(v.first.balls,2);assert.equal(v.first.batters.a1.runs,6);assert.equal(v.first.bowlers.b1.runs,7);assert.equal(v.first.extras.bye,2);assert.equal(v.state.freeHit,true);m=appendCommand(m,{runType:'wide',runs:0});assert.equal(calculateMatch(m).state.freeHit,true);assert.throws(()=>appendCommand(m,{dismissal:'bowled'}),/free hit/);m=appendCommand(m,{runs:0});assert.equal(calculateMatch(m).state.freeHit,false);assert.throws(()=>appendCommand(m,{runType:'legbye',runs:1}),/leg byes/);assert.throws(()=>appendCommand(m,{runType:'wide',noBall:true}),/overrides/)});
test('caught ends, run-out attribution, innings switch, bowler limits and undo',()=>{let m=selected();m=appendCommand(m,{runs:1});assert.equal(calculateMatch(m).state.strikerId,'a2');m=appendCommand(m,{dismissal:'caught',runs:0,completedRuns:1,fielderId:'b2'});let v=calculateMatch(m);assert.equal(v.first.wickets,1);assert.equal(v.first.bowlers.b1.wickets,1);assert.equal(v.state.nonStrikerId,'a1');assert.equal(v.state.strikerId,null);m=appendCommand(m,{command:'select',strikerId:'a3',nonStrikerId:'a1',bowlerId:'b1'});m=appendCommand(m,{runs:1,dismissal:'run_out',outId:'a1',changeEnds:true});v=calculateMatch(m);assert.equal(v.first.wickets,2);assert.equal(v.first.bowlers.b1.wickets,1);assert.equal(v.current,2);m=appendCommand(m,{command:'undo'});assert.equal(calculateMatch(m).current,1);let n=selected();for(let i=0;i<6;i++)n=appendCommand(n,{runs:0});assert.equal(calculateMatch(n).state.strikerId,'a2');assert.throws(()=>appendCommand(n,{command:'select',strikerId:'a2',nonStrikerId:'a1',bowlerId:'b1'}),/consecutive/);n=appendCommand(n,{command:'select',strikerId:'a2',nonStrikerId:'a1',bowlerId:'b2'});assert.equal(calculateMatch(n).first.bowlers.b1.maidens,1);assert.throws(()=>appendCommand(n,{command:'select',strikerId:'a1',nonStrikerId:'a2',bowlerId:'b2'}),/vacant/)});
test('short runs preserve crossed ends, retire hurt return, penalties, revised target and abandoned result',()=>{let m=selected();m=appendCommand(m,{runs:1,completedRuns:1,shortRuns:1});let v=calculateMatch(m);assert.equal(v.first.runs,0);assert.equal(v.state.strikerId,'a2');m=appendCommand(m,{command:'retire',playerId:'a2',out:false,note:'Injured'});assert.equal(calculateMatch(m).first.wickets,0);m=appendCommand(m,{command:'select',strikerId:'a2',nonStrikerId:'a1',bowlerId:'b1'});m=appendCommand(m,{command:'penalty',beneficiary:1,runs:5,note:'Umpire decision'});m=appendCommand(m,{command:'close'});m=appendCommand(m,{command:'target',target:4,maxBalls:6,note:'Official revised target'});m=appendCommand(m,{command:'select',strikerId:'b1',nonStrikerId:'b2',bowlerId:'a1'});m=appendCommand(m,{runs:4,boundary:4});assert.match(calculateMatch(m).result,/B won.*revised target/);m=appendCommand(m,{command:'undo'});m=appendCommand(m,{command:'status',status:'paused',note:'Rain'});assert.throws(()=>appendCommand(m,{runs:1}),/Resume/);m=appendCommand(m,{command:'status',status:'live',note:'Restart'});m=appendCommand(m,{command:'status',status:'abandoned',note:'Weather'});assert.match(calculateMatch(m).result,/no result/)});
async function attributedFixture(){const env=fixture(),players=[];for(let i=0;i<6;i++)players.push(await create(env,'players',{name:'Player '+i},i===0?'alice':'bob'));const id=await create(env,'matches',{name:'Attributed derby',teamA:'A',teamB:'B',overs:1});const setup={version:1,squads:{A:players.slice(0,3),B:players.slice(3)},maxBowlerOvers:1};assert.equal((await call(env,'match-setup/'+id,'POST',setup,'bob')).status,403);assert.equal((await call(env,'match-setup/'+id,'POST',{...setup,squads:{A:[players[0],players[0]],B:players.slice(3)}})).status,400);assert.equal((await call(env,'match-setup/'+id,'POST',setup)).status,200);await call(env,'score/'+id,'POST',{version:2,command:'select',strikerId:players[0],nonStrikerId:players[1],bowlerId:players[3]});await call(env,'score/'+id,'POST',{version:3,runs:6,boundary:6});return {env,id,players}}
test('squad snapshots and performance posts derive trusted statistics and enforce owner permissions',async()=>{const {env,id,players}=await attributedFixture();let r=await call(env,'scorecard/'+id);assert.equal(r.data.score.first.runs,6);assert.equal((await call(env,'match-setup/'+id,'POST',{version:4})).status,400);assert.equal((await call(env,'performance/'+id+'?playerId='+players[0])).data.batting.runs,6);assert.equal((await call(env,'performance-share/'+id,'POST',{playerId:players[0],destination:'Post'},'charlie')).status,403);r=await call(env,'performance-share/'+id,'POST',{playerId:players[0],destination:'Story',batting:{runs:999}});assert.equal(r.status,201);const post=await get(env,r.data.id);assert.equal(post.performance.batting.runs,6);assert.equal(post.sourceVersion,4);assert.ok(Date.parse(post.expiresAt)>Date.now());const match=await get(env,id);assert.equal((await call(env,'records/'+id,'PUT',{version:match.version,data:{...match,overs:20}})).status,400);assert.equal((await call(env,'records/'+id,'PUT',{version:match.version,data:{...match,name:'Renamed'}})).status,200);assert.equal((await get(env,id)).squads.A[0].name,'Player 0')});
test('cricket social validates media/live connections, stores bookmarks and expires stories',async()=>{const env=fixture();assert.equal((await call(env,'records','POST',{type:'community',data:{name:'Unconfirmed'}})).status,400);assert.equal((await call(env,'records','POST',{type:'community',data:{name:'Invalid reel',postType:'Reel',cricketOnly:true}})).status,400);assert.equal((await call(env,'records','POST',{type:'community',data:{name:'Bad live',postType:'Live',url:'https://evil.test/embed',cricketOnly:true}})).status,400);const live=await create(env,'community',{name:'Match live',postType:'Live',url:'https://www.youtube.com/watch?v=abcdefghijk',cricketOnly:true});assert.equal((await get(env,live)).embedUrl,'https://www.youtube-nocookie.com/embed/abcdefghijk');await approveFixture(env,live,1);const story=await create(env,'community',{name:'Cricket story',postType:'Story',cricketOnly:true});assert.equal((await call(env,'action/'+live,'POST',{kind:'bookmark'},'bob')).status,201);assert.equal((await call(env,'action/'+live,'POST',{kind:'report'},'bob')).status,201);assert.equal((await call(env,'action/'+live,'POST',{kind:'bookmark'},'bob')).data.removed,true);const p=await get(env,story);p.expiresAt='2000-01-01T00:00:00Z';await env.DB.prepare('UPDATE records SET data=? WHERE id=?').bind(JSON.stringify(p),story).run();assert.equal((await call(env,'data')).data.records.some(p=>p.id===story),false)});
test('automatic image screening rejects flags and outages before storage, safe images publish, videos fail closed',async()=>{
 const env=fixture(),files=new Map();env.BUCKET={async put(k,v){files.set(k,v)},async delete(k){files.delete(k)},async get(k,opts){const bytes=files.get(k);return bytes?{body:opts?.range?bytes.slice(opts.range.offset,opts.range.offset+opts.range.length):bytes}:null}};
 await call(env,'data');
 const upload=(mime,bytes)=>handle(new Request('https://cricket.test/api/assets',{method:'POST',headers:{'Content-Type':mime,'oai-authenticated-user-id':'alice','oai-authenticated-user-email':'alice@example.test'},body:bytes}),env);
 const jpeg=new Uint8Array([255,216,255,1,2,3,4]),video=new Uint8Array([0,0,0,24,102,116,121,112,1,2,3,4]);
 assert.equal((await upload('text/html',jpeg)).status,400);assert.equal((await upload('image/jpeg',jpeg)).status,503);assert.equal(files.size,0);assert.equal((await upload('video/mp4',video)).status,415);
 env.OPENAI_API_KEY='fixture-only';const original=globalThis.fetch;
 try{
 globalThis.fetch=async()=>new Response(JSON.stringify({results:[{flagged:true}]}));assert.equal((await upload('image/jpeg',jpeg)).status,422);assert.equal(files.size,0);
 globalThis.fetch=async()=>new Response('unavailable',{status:503});assert.equal((await upload('image/jpeg',jpeg)).status,503);assert.equal(files.size,0);
 globalThis.fetch=async url=>new Response(JSON.stringify(url.endsWith('/moderations')?{results:[{flagged:false}]}:{choices:[{message:{content:JSON.stringify({restricted:true,categories:['political']})}}]}));assert.equal((await upload('image/jpeg',jpeg)).status,422);assert.equal(files.size,0);
 globalThis.fetch=async url=>new Response(JSON.stringify(url.endsWith('/moderations')?{results:[{flagged:false}]}:{choices:[{message:{content:JSON.stringify({restricted:false,categories:[]})}}]}));
 const r=await upload('image/jpeg',jpeg);assert.equal(r.status,201);const asset=await r.json();assert.equal(asset.moderationStatus,'approved');
 await call(env,'data','GET',undefined,'bob');const read=user=>handle(new Request('https://cricket.test/api/assets/'+asset.id,{headers:{'oai-authenticated-user-id':user,'oai-authenticated-user-email':user+'@example.test',Range:'bytes=0-2'}}),env);assert.equal((await read('bob')).status,403);
 await create(env,'community',{name:'Cricket picture',postType:'Post',cricketOnly:true,mediaId:asset.id});const shared=await read('bob');assert.equal(shared.status,206);assert.equal(shared.headers.get('Content-Range'),'bytes 0-2/7');
 }finally{globalThis.fetch=original}
});

async function commerceFixture(country='US'){const env=fixture(),seller='bob',data={returnPolicyDeclaration:{newDays:30,usedDays:7,postage:'Buyer',inspectionDays:5,exclusions:'',accepted:true},shopName:'Test cricket shop',country,city:country==='IN'?'Bengaluru':'Worcester',postal:country==='IN'?'560001':'01608',returnAddress:'Test shop return address',contactPhone:'test-contact',carriers:country==='IN'?['India Post','Delhivery']:['USPS','UPS','FedEx'],pitchRush:true,postalCodes:country==='IN'?['560001','560002']:['01608','01609'],etaMinutes:60,expressFee:7};assert.equal((await call(env,'market/seller','POST',{data},seller)).status,200);const r=await call(env,'market/product','POST',{data:{name:'Test used bat',type:'Bat',condition:'Used',usedCondition:'Good',defects:'Scuff marks',price:80,currency:country==='IN'?'INR':'USD',stock:1,country,shippingFee:9,returnDays:14,returnShippingPayer:'Seller',returnPolicy:'Unmodified gear may be returned within 14 days.'}},seller);assert.equal(r.status,201);const productId=r.data.id,address={name:'Buyer name',phone:'buyer-private-phone',line1:'Buyer private street',city:data.city,state:country==='IN'?'KA':'MA',postal:data.postal,country};return {env,seller,productId,address}}
async function commerceOrder(f,buyer='alice',extra={}){const product=(await call(f.env,'market/catalog')).data.products.find(x=>x.id===f.productId);return call(f.env,'market/orders','POST',{productVersion:product?.version,policyVersion:product?.storePolicyVersion,productId:f.productId,quantity:1,address:f.address,delivery:'Standard',policyAccepted:true,...extra},buyer)}
async function orderAction(env,id,action,user='bob',extra={}){const o=(await call(env,'market/orders/'+id,'GET',undefined,user)).data;return call(env,'market/orders/'+id,'POST',{version:o.version,action,...extra},user)}
test('marketplace seller profiles expose only public settings; PIN eligibility and totals are server calculated',async()=>{const f=await commerceFixture('IN');const publicProfile=(await call(f.env,'market/seller/bob')).data.profile;assert.equal(publicProfile.returnAddress,undefined);assert.equal(publicProfile.contactPhone,undefined);assert.equal(publicProfile.pitchRush,true);assert.equal((await call(f.env,'market/seller')).data.profile,null);let r=await commerceOrder(f,'alice',{delivery:'PitchRush',total:0,price:0});assert.equal(r.status,201);const o=(await call(f.env,'market/orders/'+r.data.id)).data;assert.equal(o.total,87);assert.equal(o.paymentStatus,'not_collected');assert.equal(o.etaMinutes,60);assert.equal((await commerceOrder(f,'alice',{delivery:'PitchRush',address:{...f.address,postal:'600001'}})).status,400);assert.equal((await commerceOrder(f,'alice',{address:{...f.address,country:'US',postal:'01608'}})).status,400);assert.equal((await commerceOrder(f,'alice',{policyAccepted:false})).status,400);assert.equal((await commerceOrder(f,'bob')).status,400);assert.equal((await call(f.env,'market/orders/'+r.data.id,'GET',undefined,'charlie')).status,403);assert.equal((await call(f.env,'market/orders','GET',undefined,'charlie')).data.length,0);assert.equal((await call(f.env,'data','GET',undefined,'charlie')).data.records.some(x=>JSON.stringify(x).includes('Buyer private street')),false)});
test('competing order acceptance reserves one inventory unit and rejects stale/unauthorized actions',async()=>{const f=await commerceFixture(),a=await commerceOrder(f),b=await commerceOrder(f,'charlie');assert.equal(a.status,201);assert.equal(b.status,201);assert.equal((await orderAction(f.env,a.data.id,'accept','alice')).status,403);assert.equal((await orderAction(f.env,a.data.id,'accept')).status,200);assert.equal((await get(f.env,f.productId)).stock,0);assert.equal((await orderAction(f.env,b.data.id,'accept')).status,409);assert.equal((await call(f.env,'market/orders/'+b.data.id,'GET',undefined,'charlie')).data.status,'requested');assert.equal((await call(f.env,'market/orders/'+a.data.id,'POST',{version:1,action:'packing'},'bob')).status,409);assert.equal((await orderAction(f.env,a.data.id,'cancel','alice')).status,403);assert.equal((await orderAction(f.env,a.data.id,'packing')).status,200);assert.equal((await orderAction(f.env,a.data.id,'dispatch','bob',{carrier:'Unknown',tracking:'fake'})).status,400);assert.equal((await orderAction(f.env,a.data.id,'dispatch','bob',{carrier:'UPS',tracking:'TEST-TRACKING-NOT-LIVE'})).status,200);assert.equal((await orderAction(f.env,a.data.id,'delivered','bob')).status,403);assert.equal((await orderAction(f.env,a.data.id,'delivered','alice')).status,200)});
test('seller-approved returns preserve policy snapshots and support RMA codes, tracking and external resolution',async()=>{const f=await commerceFixture(),r=await commerceOrder(f),id=r.data.id;assert.equal((await call(f.env,'market/label/return/'+id)).status,400);await orderAction(f.env,id,'accept');await orderAction(f.env,id,'dispatch','bob',{carrier:'USPS',tracking:'TEST-TRACKING'});await orderAction(f.env,id,'delivered','alice');assert.equal((await orderAction(f.env,id,'return_request','alice',{reason:'Changed mind',returnNote:'Unused kit'})).status,200);assert.equal((await orderAction(f.env,id,'return_approve','alice',{carrier:'USPS',note:'Approve'})).status,403);assert.equal((await orderAction(f.env,id,'return_approve','bob',{carrier:'USPS',note:'Pack the item and purchase appropriate postage.'})).status,200);let label=await call(f.env,'market/label/return/'+id);assert.equal(label.status,200);assert.match(label.data.barcode,/^RMA-/);assert.equal(label.data.carrier,'USPS');assert.match(label.data.notice,/postage is separate/);assert.equal((await call(f.env,'market/label/return/'+id,'GET',undefined,'charlie')).status,403);assert.equal((await call(f.env,'market/label/product/'+f.productId,'GET',undefined,'bob')).status,200);assert.equal((await call(f.env,'market/label/product/'+f.productId)).status,403);assert.equal((await orderAction(f.env,id,'return_ship','alice',{tracking:'TEST-RETURN-TRACK'})).status,200);assert.equal((await orderAction(f.env,id,'return_receive')).status,200);assert.equal((await orderAction(f.env,id,'return_close','bob',{note:'Refund arranged outside platform.'})).status,200);const order=(await call(f.env,'market/orders/'+id)).data;assert.equal(order.return.status,'closed');assert.equal(order.product.returnDays,14);assert.match(order.return.refundStatus,/no refund executed/)});
test('PitchRush is seller-arranged and return windows reject late change-of-mind requests',async()=>{const f=await commerceFixture(),r=await commerceOrder(f,'alice',{delivery:'PitchRush'}),id=r.data.id;await orderAction(f.env,id,'accept');assert.equal((await orderAction(f.env,id,'dispatch','bob',{carrier:'FedEx',dispatchNote:'Local handoff'})).status,400);assert.equal((await orderAction(f.env,id,'dispatch','bob',{carrier:'Seller delivery',dispatchNote:'Seller courier handoff.'})).status,200);await orderAction(f.env,id,'delivered','alice');const row=await f.env.DB.prepare('SELECT data FROM commerce_orders WHERE id=?').bind(id).first(),d=JSON.parse(row.data);d.deliveredAt='2000-01-01T00:00:00Z';await f.env.DB.prepare('UPDATE commerce_orders SET data=? WHERE id=?').bind(JSON.stringify(d),id).run();assert.equal((await orderAction(f.env,id,'return_request','alice',{reason:'Changed mind',returnNote:'Too late'})).status,400);assert.equal((await orderAction(f.env,id,'return_request','alice',{reason:'Not as described',returnNote:'Damage not disclosed.'})).status,200)});
test('carrier documents are private to order participants and cannot be reused as product photos',async()=>{const f=await commerceFixture(),files=new Map();f.env.BUCKET={async put(k,v){files.set(k,v)},async get(k){return files.has(k)?{body:files.get(k)}:null},async delete(k){files.delete(k)}};const r=await handle(new Request('https://cricket.test/api/assets',{method:'POST',headers:{'Content-Type':'application/pdf','oai-authenticated-user-id':'bob','oai-authenticated-user-email':'bob@example.test'},body:new TextEncoder().encode('%PDF-1.7\nTest fixture, not postage')}),f.env);assert.equal(r.status,201);const asset=await r.json();const getAsset=user=>handle(new Request('https://cricket.test/api/assets/'+asset.id,{headers:{'oai-authenticated-user-id':user,'oai-authenticated-user-email':user+'@example.test'}}),f.env);assert.equal((await getAsset('alice')).status,403);const ordered=await commerceOrder(f),id=ordered.data.id;await orderAction(f.env,id,'accept');assert.equal((await orderAction(f.env,id,'dispatch','bob',{carrier:'UPS',tracking:'TEST-TRACK',labelAssetId:asset.id})).status,200);assert.equal((await getAsset('alice')).status,200);assert.equal((await getAsset('charlie')).status,403);assert.match((await getAsset('alice')).headers.get('Content-Disposition'),/attachment/);assert.equal((await call(f.env,'market/product','POST',{data:{name:'Invalid PDF photo',type:'Bat',price:10,currency:'USD',mediaId:asset.id}},'bob')).status,400);assert.equal((await call(f.env,'records','POST',{type:'marketplace',data:{name:'Bypass PDF photo',type:'Bat',price:10,currency:'USD',mediaId:asset.id}},'bob')).status,400)});

import {commissionQuote,deliveryQuote} from '../server/economics.js';
test('pilot commissions and real road tariffs reconcile in minor units',()=>{assert.equal(commissionQuote('New',100).commissionMinor,800);assert.equal(commissionQuote('Used',100).sellerMerchandiseMinor,9500);const us=deliveryQuote('US',3*1609.344,12*60);assert.equal(us.riderMinor,1015);assert.equal(us.buyerMinor,1215);const india=deliveryQuote('IN',5000,15*60);assert.equal(india.riderMinor,8000);assert.equal(india.buyerMinor,9500);assert.throws(()=>deliveryQuote('US',0,60));assert.throws(()=>deliveryQuote('IN',16000,60));assert.equal(deliveryQuote('IN',100,60).riderMinor,4500)});
