test('funded rider jobs enforce offer privacy, claim ownership, handover codes and unique held earnings',async()=>{const f=await commerceFixture(),o=await commerceOrder(f,'alice',{delivery:'PitchRush'}),id=o.data.id;await orderAction(f.env,id,'accept');let row=await f.env.DB.prepare('SELECT * FROM commerce_orders WHERE id=?').bind(id).first(),d=JSON.parse(row.data);d.paymentStatus='paid';d.riderQuote={riderMinor:1015,buyerMinor:1215,currency:'USD',distance:3,unit:'mile',durationSeconds:720,basis:'Road quote',pickup:{lat:42,lng:-71},drop:{lat:42.01,lng:-71.01},pickupAddress:'Private pickup',pickupPhone:'private'};d.deliveryFee=12.15;await f.env.DB.prepare('UPDATE commerce_orders SET data=? WHERE id=?').bind(JSON.stringify(d),id).run();assert.equal((await call(f.env,'riders/jobs/'+id,'POST',{action:'publish'},'bob')).status,200);assert.equal((await call(f.env,'riders/jobs','GET',undefined,'stranger')).data.length,0);f.env.PLATFORM_ADMIN_EMAIL='admin@example.test';f.env.PLATFORM_ADMIN_USER_ID='admin';for(const rider of ['driver','driver2']){await call(f.env,'riders/profile','POST',{data:{name:rider,phone:'test',country:'US',city:'Worcester',vehicle:'Car',postalCodes:'01608',ageConfirmed:true,agreement:true}},rider);let p=(await call(f.env,'riders/profile','GET',undefined,rider)).data.profile;await call(f.env,'riders/approve','POST',{owner:rider,version:p.version,status:'approved',note:'Operator test review'},'admin');p=(await call(f.env,'riders/profile','GET',undefined,rider)).data.profile;await call(f.env,'riders/profile','POST',{version:p.version,data:{...p,postalCodes:'01608',available:true}},rider)}let job=(await call(f.env,'riders/jobs','GET',undefined,'driver')).data[0];assert.equal(job.pickupAddress,undefined);assert.equal(job.handoverCode,undefined);const act=async(action,by='driver',extra={})=>{const j=(await call(f.env,'riders/jobs','GET',undefined,by)).data.find(x=>x.id===job.id);return call(f.env,'riders/jobs/'+job.id,'POST',{version:j?.version||1,action,...extra},by)};assert.equal((await act('claim')).status,200);assert.equal((await act('claim','driver2')).status,409);job=(await call(f.env,'riders/jobs','GET',undefined,'driver')).data[0];assert.equal(job.pickupAddress,'Private pickup');assert.equal(job.handoverCode,undefined);assert.equal(job.handoverHash,undefined);assert.equal((await act('picked_up')).status,200);assert.equal((await act('complete','driver',{method:'Handover',code:'000000'})).status,403);const buyerJob=(await call(f.env,'riders/jobs')).data[0];assert.match(buyerJob.handoverCode,/^\d{6}$/);assert.equal((await act('complete','driver',{method:'Handover',code:buyerJob.handoverCode})).status,200);assert.equal((await call(f.env,'market/orders/'+id)).data.status,'delivered');assert.equal((await act('finalize')).status,200);const ledger=(await call(f.env,'pay/ledger','GET',undefined,'driver')).data;assert.equal(ledger.length,1);assert.equal(ledger[0].amountMinor,1015);assert.equal(ledger[0].status,'held');assert.equal((await call(f.env,'pay/ledger','GET',undefined,'bob')).data.length,1)});
test('settlement claim prevents duplicate transfers and refunds cannot re-mark orders paid',async()=>{const f=await commerceFixture(),o=await commerceOrder(f),id=o.data.id;await orderAction(f.env,id,'accept');let row=await f.env.DB.prepare('SELECT * FROM commerce_orders WHERE id=?').bind(id).first(),d=JSON.parse(row.data);d.paymentStatus='paid';d.status='delivered';d.deliveredAt='2026-01-01T00:00:00Z';await f.env.DB.prepare('UPDATE commerce_orders SET data=? WHERE id=?').bind(JSON.stringify(d),id).run();await f.env.DB.prepare('INSERT INTO payments(id,order_id,provider,provider_id,data,created) VALUES(?,?,?,?,?,?)').bind('pay',id,'stripe','cs_test',JSON.stringify({status:'paid',paymentIntent:'pi_test'}),'2026-01-01').run();await f.env.DB.prepare('INSERT INTO payment_accounts(id,owner,role,provider,account_id,created) VALUES(?,?,?,?,?,?)').bind('acc','bob','seller','stripe','acct_test','2026-01-01').run();await f.env.DB.prepare('INSERT INTO payout_ledger(id,order_id,owner,role,data,created) VALUES(?,?,?,?,?,?)').bind('ledger',id,'bob','seller',JSON.stringify({status:'held',amountMinor:8500,currency:'USD',releaseAt:'2026-01-01'}),'2026-01-01').run();f.env.PLATFORM_ADMIN_EMAIL='admin@example.test';f.env.PLATFORM_ADMIN_USER_ID='admin';f.env.STRIPE_SECRET_KEY='test-placeholder';const original=globalThis.fetch;let transfers=0;try{globalThis.fetch=async url=>{if(String(url).endsWith('/transfers')){transfers++;return Response.json({id:'tr_test'})}if(String(url).includes('/accounts/'))return Response.json({capabilities:{transfers:'active'}});return Response.json({latest_charge:'ch_test'})};const results=await Promise.all([call(f.env,'pay/release','POST',{id:'ledger'},'admin'),call(f.env,'pay/release','POST',{id:'ledger'},'admin')]);assert.ok(results.some(x=>x.status===200));assert.ok(results.every(x=>[200,409].includes(x.status)));assert.equal(transfers,1);const ledger=(await call(f.env,'pay/ledger','GET',undefined,'bob')).data[0];assert.equal(ledger.status,'paid');assert.equal(ledger.transferId,'tr_test');d.return={status:'received'};await f.env.DB.prepare('UPDATE commerce_orders SET data=? WHERE id=?').bind(JSON.stringify(d),id).run();assert.equal((await call(f.env,'pay/refund/'+id,'POST',{},'admin')).status,409);await f.env.DB.prepare('DELETE FROM payout_ledger WHERE id=?').bind('ledger').run();globalThis.fetch=async()=>Response.json({id:'re_test',status:'succeeded'});assert.equal((await call(f.env,'pay/refund/'+id,'POST',{},'admin')).data.status,'refunded');assert.equal((await call(f.env,'pay/verify/'+id,'POST',{})).data.status,'refunded');assert.equal((await call(f.env,'market/orders/'+id)).data.paymentStatus,'refunded')}finally{globalThis.fetch=original}});

import {canonicalBrand,matchesGear,sortGear,brandOptions} from '../public/shop-catalog.js';
import {declarePolicy,policyForStore} from '../server/store-policy.js';
test('brand filters work across equipment and canonicalize One8 and SS while combining size and stock',()=>{assert.equal(canonicalBrand('one 8'),'One8');assert.equal(canonicalBrand('SS'),'SS TON');const p={name:'Match shoe',brand:'one8',type:'Shoes',currency:'INR',price:2000,stock:1,size:'UK 9',audience:'Adult',gender:'Men'};assert.equal(matchesGear(p,{brands:['One8'],category:'Shoes',currency:'INR',min:1500,max:2500,inStock:true,size:'9'}),true);assert.equal(matchesGear(p,{brands:['One8'],category:'Bat'}),false);assert.equal(matchesGear({...p,stock:0},{inStock:true}),false);assert.equal(matchesGear(p,{brands:['MRF']}),false);assert.ok(brandOptions([]).includes('One8'));assert.equal(sortGear([{name:'B',currency:'USD',price:1},{name:'A',currency:'INR',price:2000}],'price-low')[0].currency,'INR')});
test('store policy declaration validates windows, postage, consent and generates clear new/used terms',()=>{assert.throws(()=>declarePolicy({accepted:false}));assert.throws(()=>declarePolicy({accepted:true,newDays:91,usedDays:7,postage:'Buyer',inspectionDays:5}));const p=declarePolicy({accepted:true,newDays:30,usedDays:0,postage:'Buyer',inspectionDays:5,exclusions:'Personalized items'});assert.equal(policyForStore(p,'New').returnDays,30);assert.equal(policyForStore(p,'Used').returnDays,0);assert.match(policyForStore(p,'Used').returnPolicy,/No change-of-mind/);assert.match(policyForStore(p,'New').returnPolicy,/Seller pays approved return postage/);assert.match(policyForStore(p,'New').returnPolicy,/Applicable consumer rights/)});
test('seller registration requires policy consent; inherited policies snapshot per order and private addresses stay private',async()=>{const f=await commerceFixture();let settings=(await call(f.env,'market/seller','GET',undefined,'bob')).data.profile;assert.equal((await call(f.env,'market/seller','POST',{version:settings.version,data:{...settings,returnPolicyDeclaration:{...settings.returnPolicyDeclaration,accepted:false}}},'bob')).status,400);const p=await call(f.env,'market/product','POST',{data:{name:'One8 shoe',brand:'one 8',type:'Shoes',price:100,currency:'USD',stock:2,country:'US',useStorePolicy:true,condition:'New'}},'bob');assert.equal(p.status,201);const cat=(await call(f.env,'market/catalog')).data,item=cat.products.find(x=>x.id===p.data.id);assert.equal(item.brand,'One8');assert.equal(item.returnDays,30);assert.equal(cat.sellers.bob.returnAddress,undefined);assert.equal(cat.sellers.bob.returnPolicyDeclaration.accepted,true);const buy=await commerceOrder({...f,productId:p.data.id});assert.equal(buy.status,201);let order=(await call(f.env,'market/orders/'+buy.data.id)).data;assert.equal(order.product.returnDays,30);assert.equal(order.product.policySource,'store');settings=(await call(f.env,'market/seller','GET',undefined,'bob')).data.profile;await call(f.env,'market/seller','POST',{version:settings.version,data:{...settings,returnPolicyDeclaration:{...settings.returnPolicyDeclaration,newDays:7}}},'bob');assert.equal((await call(f.env,'market/catalog')).data.products.find(x=>x.id===p.data.id).returnDays,7);assert.equal((await call(f.env,'market/orders/'+buy.data.id)).data.product.returnDays,30);await orderAction(f.env,buy.data.id,'accept');await orderAction(f.env,buy.data.id,'dispatch','bob',{carrier:'UPS',tracking:'TEST'});await orderAction(f.env,buy.data.id,'delivered','alice');await orderAction(f.env,buy.data.id,'return_request','alice',{reason:'Wrong item',returnNote:'Incorrect item'});await orderAction(f.env,buy.data.id,'return_approve','bob',{carrier:'UPS',note:'Return after approval'});assert.equal((await call(f.env,'market/orders/'+buy.data.id)).data.return.postagePayer,'Seller')});
import {loadMarketplace,marketplace,handleMarket,marketInput} from '../public/marketplace.js';
test('shop view wires brand/category filtering, safe listing rendering, footer and saved new/used gear',async()=>{const products=[{id:'one',owner:'bob',name:'One8 shoe',brand:'One8',type:'Shoes',condition:'New',price:50,currency:'USD',stock:1},{id:'used',owner:'bob',name:'Used One8 shoe',brand:'one 8',type:'Shoes',condition:'Used',price:25,currency:'USD',stock:1},{id:'other',owner:'bob',name:'<Unsafe bat>',brand:'MRF',type:'Bat',condition:'New',price:80,currency:'USD',stock:1}],c={user:()=> 'alice',currentRoute:()=> 'marketplace',render(){},refresh:async()=>{},toast(){},requireUser:()=>true,acted:()=>true,$:()=>({close(){}}),api:async path=>path==='market/catalog'?{products,sellers:{bob:{shopName:'Real store'}}}:path==='market/orders'?[]:path==='market/seller'?{profile:null}:{stripe:false,razorpay:false}};await loadMarketplace(c);await handleMarket({dataset:{market:'brand',id:'One8'}},c);let html=marketplace(c);assert.match(html,/id="product-one"/);assert.doesNotMatch(html,/id="product-other"/);assert.match(html,/marketBrand/);assert.match(html,/shop-footer/);marketInput({target:{id:'marketCategory',value:'Bat'}},c);assert.doesNotMatch(marketplace(c),/id="product-one"/);await handleMarket({dataset:{market:'reset'}},c);assert.match(marketplace(c),/&lt;Unsafe bat&gt;/);await handleMarket({dataset:{market:'saved'}},c);html=marketplace(c);assert.match(html,/id="product-one"/);assert.match(html,/id="product-used"/)});
test('complete match setup validates roles, initializes openers, persists details and locks after scoring',async()=>{
 const env=fixture(),players=[];for(let i=0;i<6;i++)players.push(await create(env,'players',{name:'Setup player '+i,role:'All-rounder',batting:'Right hand',bowling:'Right-arm pace'}));
 const id=await create(env,'matches',{name:'Setup match',teamA:'A',teamB:'B',overs:1});
 const payload={version:1,squads:{A:players.slice(0,3),B:players.slice(3)},maxBowlerOvers:1,details:{name:'Complete match',location:'Test ground',date:'2026-10-08',time:'09:00',format:'Limited overs'},matchSetup:{teams:{A:{captainId:players[0],wicketkeeperId:players[1]},B:{captainId:players[3],wicketkeeperId:players[4]}},officials:{bowlerEnd:'Test umpire A',squareLeg:'Test umpire B'},tossWinner:'A',tossDecision:'bat'},opening:{strikerId:players[0],nonStrikerId:players[1],bowlerId:players[3]}};
 assert.equal((await call(env,'match-setup/'+id,'POST',{...payload,matchSetup:{...payload.matchSetup,teams:{...payload.matchSetup.teams,A:{captainId:players[3],wicketkeeperId:players[1]}}}})).status,400);
 assert.equal((await call(env,'match-setup/'+id,'POST',{...payload,opening:{...payload.opening,bowlerId:players[0]}})).status,400);
 assert.equal((await call(env,'match-setup/'+id,'POST',{...payload,matchSetup:{...payload.matchSetup,tossDecision:'bowl'}})).status,400);
 assert.equal((await call(env,'match-setup/'+id,'POST',payload,'bob')).status,403);
 assert.equal((await call(env,'match-setup/'+id,'POST',payload)).status,200);
 let match=await get(env,id);assert.equal(match.name,'Complete match');assert.equal(match.squads.A[0].bowling,'Right-arm pace');assert.equal(match.scoringConfig.matchSetup.teams.B.wicketkeeperId,players[4]);
 let card=(await call(env,'scorecard/'+id)).data;assert.equal(card.score.state.bowlerId,players[3]);assert.equal(card.score.state.strikerId,players[0]);
 assert.equal((await call(env,'match-setup/'+id,'POST',payload)).status,409);
 assert.equal((await call(env,'match-setup/'+id,'POST',{...payload,version:2})).status,200);
 assert.equal((await call(env,'score/'+id,'POST',{version:3,runs:4,boundary:4})).status,200);
 assert.equal((await call(env,'match-setup/'+id,'POST',{...payload,version:4})).status,400);
 match=await get(env,id);assert.equal((await call(env,'records/'+id,'PUT',{version:match.version,data:{...match,name:'Updated match name'}})).status,200);
 card=(await call(env,'scorecard/'+id)).data;assert.equal(card.scoringConfig.matchSetup.officials.bowlerEnd,'Test umpire A');assert.equal(card.score.first.runs,4);
 const league=await create(env,'leagues',{name:'Setup test league'}),competitionMatch=await create(env,'matches',{name:'Pending setup',teamA:'A',teamB:'B',overs:1,leagueId:league});
 const proposal=await call(env,'match-setup/'+competitionMatch,'POST',payload);assert.equal(proposal.status,202);assert.equal((await get(env,competitionMatch)).proScoring,undefined);
 assert.equal((await call(env,'governance/changes/'+proposal.data.id,'POST',{decision:'approve'},'bob')).status,403);
 assert.equal((await call(env,'governance/changes/'+proposal.data.id,'POST',{decision:'approve'})).status,200);
 card=(await call(env,'scorecard/'+competitionMatch)).data;assert.equal(card.scoringConfig.matchSetup.teams.A.captainId,players[0]);assert.equal(card.score.state.bowlerId,players[3]);
});
test('feature APIs reject anonymous and incomplete accounts without disabling onboarding',async()=>{
 const env=fixture();env.skipAutoProfile=true;
 assert.equal((await call(env,'directory/venues','GET',undefined,null)).status,401);
 assert.equal((await call(env,'data')).data.code,'PROFILE_REQUIRED');assert.equal((await call(env,'account')).data.profile,null);
 const data={name:'Gate test member',city:'Boston',country:'US',roles:['player'],primaryRole:'player'};
 assert.equal((await call(env,'account','POST',{data})).status,400);
 assert.equal((await call(env,'account','POST',{data:{...data,termsAccepted:true,privacyAccepted:true}})).status,200);
 assert.equal((await call(env,'data')).status,200);assert.equal((await call(env,'directory/venues')).status,200);
 assert.equal((await call(env,'account','DELETE')).status,200);assert.equal((await call(env,'data')).status,403);
});
